
#' Save a letsR object
#'
#' @author Bruno Vilela
#'
#' @description
#' Save PresenceAbsence objects and other letsR objects generated by
#' functions such as \code{\link{lets.envpam}} and
#' \code{\link{lets.attrpam}}. All SpatRaster components are
#' automatically prepared for serialization, allowing the complete
#' object to be restored using \code{\link{lets.load}}.
#'
#' Supports objects returned by \code{\link{lets.presab}},
#' \code{\link{lets.envpam}}, and \code{\link{lets.attrpam}}.
#'
#' @param pam A letsR object containing matrices and/or SpatRaster
#'   components.
#' @param ... Additional arguments passed to \code{\link{save}}.
#'
#' @return Invisibly returns NULL. The object is saved to a file.
#'
#' @seealso \code{\link{lets.load}}
#' @seealso \code{\link{lets.presab}}
#' @seealso \code{\link{lets.envpam}}
#' @seealso \code{\link{lets.attrpam}}
#'
#' @examples \dontrun{
#' data(PAM)
#' lets.save(PAM, file = "PAM.RData")
#' PAM <- lets.load("PAM.RData")
#' }
#'
#' @export
lets.save <- function(pam, ...) {
  
  if (!is.list(pam)) {
    stop("'pam' must be a list.")
  }
  
  # Identify all SpatRaster components
  raster_idx <- vapply(
    pam, inherits, logical(1), "SpatRaster"
  )
  
  # Wrap raster components for serialization
  pam[raster_idx] <- lapply(
    pam[raster_idx], terra::wrap
  )
  
  # Save the complete object
  base::save(pam, ...)
}


#' Load a letsR object
#'
#' @author Bruno Vilela
#'
#' @description
#' Load a letsR object previously saved using
#' \code{\link{lets.save}}. All packed raster components
#' are automatically restored as SpatRaster objects.
#'
#' @param file A character string specifying the file to load.
#'
#' @return The restored letsR object, including its matrices,
#'   raster components, and other attributes.
#'
#' @seealso \code{\link{lets.save}}
#' @seealso \code{\link{lets.presab}}
#' @seealso \code{\link{lets.envpam}}
#' @seealso \code{\link{lets.attrpam}}
#'
#' @examples \dontrun{
#' data(PAM)
#' lets.save(PAM, file = "PAM.RData")
#' PAM <- lets.load("PAM.RData")
#' }
#'
#' @export
lets.load <- function(file) {
  
  e <- base::new.env()
  
  # Load object into temporary environment
  name_file <- base::load(file, envir = e)
  
  if (length(name_file) != 1L) {
    stop("The file must contain exactly one object.")
  }
  
  pam <- base::get(name_file, envir = e)
  
  if (!is.list(pam)) {
    stop("The loaded object must be a list.")
  }
  
  # Identify packed SpatRaster components
  raster_idx <- vapply(
    pam, inherits, logical(1), "PackedSpatRaster"
  )
  
  # Restore original raster components
  pam[raster_idx] <- lapply(
    pam[raster_idx], terra::unwrap
  )
  
  return(pam)
}
